$ErrorActionPreference='Stop'
function A([bool]$ok,[string]$m){if(-not $ok){throw $m}}
function Godot([string]$app){$r=Join-Path $app 'toolchains\godot';$g=Get-ChildItem $r -Filter '*_console.exe' -File -ErrorAction SilentlyContinue|Select-Object -First 1;if(-not$g){$g=Get-ChildItem $r -Filter 'Godot_v4*.exe' -File -ErrorAction SilentlyContinue|Where-Object{$_.Name-notmatch'_console\.exe$'}|Select-Object -First 1};if(-not$g){throw'Bundled Godot missing'};return $g.FullName}
function Smoke([string]$g,[string]$n){$d=Join-Path $env:RUNNER_TEMP "smoke-final-$n";Remove-Item $d -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Force $d|Out-Null;"config_version=5`n[application]`nrun/main_scene=`"res://main.tscn`"`n"|Set-Content -Encoding utf8NoBOM (Join-Path $d 'project.godot');"extends Node`nfunc _ready():`n print(`"FORGE_GODOT_SMOKE_OK`")`n get_tree().quit()`n"|Set-Content -Encoding utf8NoBOM (Join-Path $d 'main.gd');"[gd_scene load_steps=2 format=3]`n[ext_resource path=`"res://main.gd`" type=`"Script`" id=`"1`"]`n[node name=`"Main`" type=`"Node`"]`nscript=ExtResource(`"1`")`n"|Set-Content -Encoding utf8NoBOM (Join-Path $d 'main.tscn');$o=(&$g --headless --path $d 2>&1|Out-String);A ($LASTEXITCODE-eq 0-and$o-match'FORGE_GODOT_SMOKE_OK') "Final Godot smoke failed $o"}
