$name='Forge-Studio-Setup-0.38.3-x64.exe';$installer="builder/release/$name";$blockmap="$installer.blockmap";$latest='builder/release/latest.yml';foreach($f in @($installer,$blockmap,$latest)){A (Test-Path $f) "Missing artifact $f"};A ((Get-Item $installer).Length-gt 150MB) 'Installer too small to retain bundled Godot.';$feed=Get-Content $latest -Raw;A ($feed-match'(?m)^version:\s*0\.38\.3\s*$'-and$feed-match[regex]::Escape($name)) 'Generated updater feed is wrong.'
